/**
 * HEALTH SCORE ENGINE — Fórmula y Pesos
 * =======================================
 * El health score (0-100) mide el estado de salud de una línea y determina
 * si opera al máximo rendimiento (score alto) o de forma conservadora (score bajo).
 *
 * COMPONENTES — máximo posible entre corchetes:
 *
 *  1. success_rate_score  [0–40 pts]  ← mayor peso
 *     Tasa de envíos exitosos en los últimos 7 días.
 *     Fórmula: round((sent_7d / total_7d) * 40)
 *     Si total_7d < 10 (historial insuficiente) se asume 80% → 32 pts.
 *
 *  2. ban_penalty  [0–30 pts]
 *     Ausencia de bans en los últimos 7 días.
 *     Fórmula: max(0, 30 − banned_7d × 15)
 *     → 0 bans = 30 pts  |  1 ban = 15 pts  |  ≥2 bans = 0 pts
 *
 *  3. recency_score  [0–20 pts]
 *     Tiempo transcurrido desde el último error. Premia la recuperación.
 *     → Sin error previo o error > 24h  = 20 pts
 *     → Error hace 12–24h              = 12 pts
 *     → Error hace 6–12h               =  6 pts
 *     → Error hace 1–6h                =  2 pts
 *     → Error en la última hora        =  0 pts  (riesgo inmediato)
 *
 *  4. volume_score  [0–10 pts]
 *     Escala logarítmica de mensajes exitosos en 7 días.
 *     → > 30 enviados = 10 pts | > 15 = 8 pts | > 5 = 5 pts | > 0 = 2 pts
 *
 *  5. burst_penalty  [−15 a 0 pts]  ← RESTA al total
 *     Detecta ráfagas de errores en las últimas 6 horas (señal de riesgo inmediato).
 *     → errors_6h ≥ 3 → −15 pts  (frenar agresivamente)
 *     → errors_6h ≥ 1 →  −5 pts  (señal de precaución)
 *
 * SCORE FINAL = clamp(componentes + burst_penalty, 0, 100)
 *
 * OVERRIDES ADAPTATIVOS sobre la configuración de fase:
 *   score ≥ 85  → línea sana:      +20% daily_limit, −20% delay
 *   score ≤ 60  → línea en riesgo: −30% daily_limit, +40% delay
 *   60 < score < 85 → configuración de fase sin modificar (comportamiento neutral)
 *
 * CASO ESPECIAL — línea nueva (total_7d === 0):
 *   Score fijo = 70 (neutro-conservador), sin override.
 *   Evita penalizar una línea que aún no tiene historial real.
 */
const healthResult = $input.first().json;
const job          = $('Trigger – Recibe Job de Orchestrador').first().json;

const hasError = !healthResult || healthResult.error || healthResult.message;
const stats    = hasError ? {} : healthResult;

const sent7d   = Math.max(0, stats.sent_7d   || 0);
const failed7d = Math.max(0, stats.failed_7d  || 0);
const banned7d = Math.max(0, stats.banned_7d  || 0);
const errors6h = Math.max(0, stats.errors_6h  || 0);
const total7d  = Math.max(0, stats.total_7d   || 0);

const baseDailyLimit = job.phase_daily_limit || job.daily_limit || 20;
const baseMinDelay   = job.phase_min_delay   || 10;
const baseMaxDelay   = job.phase_max_delay   || 30;

if (total7d === 0) {
  return [{ json: {
    ...job,
    health_score:         70,
    health_components:    { success_rate_score: 28, ban_penalty: 30, recency_score: 12, volume_score: 0, burst_penalty: 0 },
    adaptive_daily_limit: baseDailyLimit,
    adaptive_min_delay:   baseMinDelay,
    adaptive_max_delay:   baseMaxDelay
  } }];
}

const successRatio     = total7d > 10 ? sent7d / total7d : 0.8;
const successRateScore = Math.round(Math.min(40, Math.max(0, successRatio * 40)));
const banPenalty       = Math.max(0, 30 - (banned7d * 15));

let recencyScore = 20;
if (stats.last_error_at) {
  const hoursSince = (Date.now() - new Date(stats.last_error_at).getTime()) / 3600000;
  if      (hoursSince < 1)  recencyScore = 0;
  else if (hoursSince < 6)  recencyScore = 2;
  else if (hoursSince < 12) recencyScore = 6;
  else if (hoursSince < 24) recencyScore = 12;
  else                      recencyScore = 20;
}

let volumeScore = 0;
if      (sent7d > 30) volumeScore = 10;
else if (sent7d > 15) volumeScore =  8;
else if (sent7d > 5)  volumeScore =  5;
else if (sent7d > 0)  volumeScore =  2;

const burstPenalty = errors6h >= 3 ? -15 : (errors6h >= 1 ? -5 : 0);
const healthScore  = Math.min(100, Math.max(0, successRateScore + banPenalty + recencyScore + volumeScore + burstPenalty));

const healthComponents = { success_rate_score: successRateScore, ban_penalty: banPenalty, recency_score: recencyScore, volume_score: volumeScore, burst_penalty: burstPenalty };

let adaptiveDailyLimit = baseDailyLimit;
let adaptiveMinDelay   = baseMinDelay;
let adaptiveMaxDelay   = baseMaxDelay;

if (healthScore >= 85) {
  adaptiveDailyLimit = Math.round(adaptiveDailyLimit * 1.20);
  adaptiveMinDelay   = Math.max(5, Math.round(adaptiveMinDelay * 0.80));
  adaptiveMaxDelay   = Math.max(adaptiveMinDelay, Math.round(adaptiveMaxDelay * 0.80));
} else if (healthScore <= 60) {
  adaptiveDailyLimit = Math.max(1, Math.round(adaptiveDailyLimit * 0.70));
  adaptiveMinDelay   = Math.round(adaptiveMinDelay * 1.40);
  adaptiveMaxDelay   = Math.round(adaptiveMaxDelay * 1.40);
}

return [{ json: { ...job, health_score: healthScore, health_components: healthComponents, adaptive_daily_limit: adaptiveDailyLimit, adaptive_min_delay: adaptiveMinDelay, adaptive_max_delay: adaptiveMaxDelay } }];

/*
 * Valida los campos requeridos y calcula el delay final con jitter ±10%
 * aplicado sobre el rango adaptativo generado por el Health Score.
 */
const job = $input.first().json;

const required = ['warmup_number_id', 'instance_name', 'recipient_phone', 'message_text', 'contact_id'];
const missing  = required.filter(f => !job[f]);
if (missing.length) throw new Error(`Job inválido — faltan campos: ${missing.join(', ')}`);

const minDelay = Math.max(5, job.adaptive_min_delay || job.phase_min_delay || 10);
const maxDelay = Math.max(minDelay, job.adaptive_max_delay || job.phase_max_delay || 30);
const base     = Math.floor(Math.random() * (maxDelay - minDelay + 1)) + minDelay;
const jitter   = Math.round(base * 0.10 * (Math.random() * 2 - 1));
const delaySec = Math.min(600, Math.max(5, base + jitter));

return [{ json: { ...job, delay_sec: delaySec } }];

/*
 * Clasifica el resultado de Evolution API (intento 1/3).
 *
 * Tipos de error y comportamiento:
 *   permanent_ban   → 403/401 o keywords de ban       — NO reintentar, marcar como banned
 *   rate_limited    → 429 o "rate limit" en body       — SÍ reintentar (backoff 2s)
 *   temporary_block → 5xx o "unavailable" en body      — NO reintentar (fallo de infra)
 *   network_error   → timeout, status 0, sin respuesta — SÍ reintentar (backoff 2s)
 *
 * Regla: solo reintentan errores verdaderamente transitorios (network_error, rate_limited).
 * temporary_block no reintenta para no agravar el estado del servidor destino.
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: !success && (errorType === 'network_error' || errorType === 'rate_limited'), status_code: status, attempt: 1 } }];

/*
 * Clasifica el resultado de Evolution API (intento 2/3).
 * Si falla con error transitorio → reintenta con backoff 4s (intento final).
 * Misma lógica de clasificación que intento 1.
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: !success && (errorType === 'network_error' || errorType === 'rate_limited'), status_code: status, attempt: 2 } }];

/*
 * Clasifica el resultado del último intento (3/3).
 * needs_retry = false SIEMPRE — el flujo avanza al registro sin importar el resultado.
 * Misma lógica de clasificación que intentos anteriores.
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: false, status_code: status, attempt: 3 } }];
